INSERT INTO problems (difficulty, opponent_name, opponent_message, reply_text, sort_order) VALUES
('beginner', '田中', 'PR #123 のレビューお願いできますか？', '確認します。少々お待ちください。差分見たらコメント多すぎて寿司打みたくなってきました。', 1),
('beginner', '鈴木', '今日のスタンドアップ、10分遅れても大丈夫ですか？', '大丈夫です。議事録は後で共有します。朝のビルドが私より先に起きてました。', 2),
('beginner', '佐藤', 'README のタイポ直しました。マージしていいですか？', 'LGTM です。マージお願いします。README、今日も優しい誤字で挨拶してきましたね。', 3),
